<?php
declare(strict_types=1);
require_once __DIR__.'/../server/_core/CommerceMailTemplates.php';
use BYPCMS\Core\CommerceMailTemplates as Templates;
$checks=0;function check(bool $ok,string $why):void{global $checks;if(!$ok)throw new RuntimeException($why);$checks++;}
$samples=Templates::samples('https://example.test');check(count($samples)>50,'separate business scenarios and audiences');
foreach($samples as $s){check(strlen($s['subject'])<=190&&!preg_match('/[\r\n]/',$s['subject']),'safe subject');check(str_contains($s['html'],'multipart')===false&&str_contains($s['html'],'<html lang="ru">'),'HTML document');check(str_contains($s['message'],'https://example.test/'.($s['audience']==='owner'?'owner/':'account/')),'audience-specific authenticated cabinet');check(!preg_match('~<script|<img|javascript:|<form~i',$s['html']),'no scripts, trackers or forms');if($s['template_key']==='paid')check(str_contains($s['message'],'Повторно оплачивать'),'no duplicate payment request');if($s['kind']==='service'&&$s['template_key']==='paid')check(str_contains($s['message'],'Лицензия в этот заказ не входит'),'services do not promise licence');if($s['kind']==='test')check(str_contains($s['message'],'Реального списания денег не было'),'test order marked');if($s['kind']==='mixed'&&$s['template_key']==='ready')check(str_contains($s['message'],'работы выполняются и принимаются отдельно'),'licence delivery does not claim completion of work');}
$o=['id'=>1,'edition'=>'content','kind'=>'purchase','amount_minor'=>790000,'domain'=>'</td><script>alert(1)</script>','mode'=>'live','items_json'=>'{"secret":"must-not-leak"}','license_key'=>'must-not-leak','account'=>'must-not-leak'];
foreach(Templates::EVENTS as $event){$s=Templates::render($o,$event,'customer','https://example.test');check(!str_contains($s['html'],'<script>')&&str_contains($s['html'],'&lt;script&gt;'),'escape dynamic text');check(!str_contains($s['message'].$s['html'],'must-not-leak'),'never include keys, bank details or internal payload');}
$renew=Templates::render(array_replace($o,['kind'=>'renewal','renewed_until'=>'2028-11-13']),'ready','customer','https://example.test');check(str_contains($renew['subject'],'продлена')&&str_contains($renew['message'],'2028-11-13'),'renewal has actual resulting date');
foreach(['https://user:secret@example.test','javascript:alert(1)','https://example.test/#secret']as $bad){try{Templates::render($o,'ready','customer',$bad);throw new RuntimeException('Unsafe origin accepted');}catch(InvalidArgumentException $e){check(true,'unsafe origin rejected');}}
echo "$checks mail template, escaping and scenario checks passed\n";
